// v26.xx (flow7), HIS ANSWER (2026-10-14), the raid events, the third: BOUNTY PILLAGER, "a marked crew boss with a big score reward, who hunts you". A 15 s
// warning over a ring where he will come in (700 to 1,000 from you, off the rings), then a hostile pillager of the wave kind (arcadeWaveRaider: the CAREER
// save never hears of him) steps in with four times the health, a full rig of plate (at least 100) and a rich bag (a cache roll and two safe rolls on top of his
// own) for the body to drop. HE HUNTS YOU: every frame he is put on the chase toward where you stand, alert held up, so he comes for you through the streets
// whether or not he has seen you. The ring, the mark and BOUNTY $1,500 follow him. Put him down (the kill is yours) and the BOUNTY is paid into the run
// score at once (DEMO score, CAREER raid score); if something else killed him nothing is paid. After 150 s on the hunt he slips away. Made on a side stream
// of the event, so the seeded stream and the CAREER save are untouched. DEMO and CAREER are the same.
var BOUNTY={pay:1500};
EVENTS.bounty={name:'BOUNTY PILLAGER',sub:'HE HUNTS YOU',warn:15,dur:150,r:220,fade:4,col:'#ff5a4a',
  mx:function(ev){ var e=ev.d.e; return (ev.ph!=='warn'&&e&&e.hp>0)?e.x:ev.x; },
  my:function(ev){ var e=ev.d.e; return (ev.ph!=='warn'&&e&&e.hp>0)?e.y:ev.y; },
  pick:function(ev){
    var p=G.player, S=null;
    evStream(ev,function(){
      var k, a, d, x, y;
      for(k=0;k<80&&!S;k++){
        a=rr()*6.2832; d=700+rr()*300; x=p.x+Math.cos(a)*d; y=p.y+Math.sin(a)*d;
        if(x>300&&y>300&&x<WORLD_W-300&&y<WORLD_H-300&&spotFree(G.map,x,y,40)&&navReachable(G.map,x,y)&&!shutRoomAt(G.map,x,y)&&!flowZoneNear(x,y,350)) S={x:x,y:y};
      }
    });
    if(!S) return false;
    ev.x=S.x; ev.y=S.y;
    return true;
  },
  start:function(ev){
    var e=null, seed=(((G.seed>>>0)^Math.imul((ev.n|0)+71,2654435761))>>>0)||1;
    sideStream(seed,EV.tag+6,function(){
      var k;
      e=arcadeWaveRaider(ev.x,ev.y);
      e.hp=e.maxhp=Math.round(e.maxhp*4); e.armorCap=Math.max(e.armorCap||0,100); e.armor=e.armorCap; e.bounty=1;
      e.bag.push(rollLoot(LOOT.cache),rollLoot(LOOT.safe),rollLoot(LOOT.safe));
    });
    e.state='chase'; e.alert=3; e.tx=G.player.x; e.ty=G.player.y;
    G.ents.push(e);
    ev.d.e=e; ev.d.over=0; ev.r=60;
    try{ say('BOUNTY ON THE MAP','warn',{sub:'HE HUNTS YOU  $'+BOUNTY.pay}); }catch(_bs){}
  },
  tick:function(ev,dt){
    var e=ev.d.e, p=G.player, down;
    if(ev.d.over) return;
    if(!e){ ev.d.over=1; return; }
    down=!(e.hp>0)||e.downed||e.finished||G.ents.indexOf(e)<0;
    if(down){
      ev.d.over=1;
      if(e.byPlayer!==false){ flowChip(BOUNTY.pay,'BOUNTY CLAIMED','BOUNTY PILLAGER'); ev.d.won=1; }
      else { try{ say('BOUNTY GONE','info',{sub:'NOT YOUR KILL'}); }catch(_bg){} }
      return;
    }
    e.state='chase'; e.alert=3; e.chaseHold=0; e.tx=p.x; e.ty=p.y;
  },
  done:function(ev){ return !!ev.d.over; },
  end:function(ev){
    var e=ev.d.e, k;
    if(!ev.d.over&&e&&e.hp>0){
      k=G.ents.indexOf(e); if(k>=0) G.ents.splice(k,1);
      try{ say('BOUNTY SLIPPED AWAY','info'); }catch(_be){}
    }
  },
  live:function(ev){ return 'HUNTING YOU'; },
  draw:function(ev,c,s,q,z){
    var e=ev.d.e, U=function(v){ return LH(v)*z; };
    if(ev.ph!=='live'||!e||!(e.hp>0)) return;
    c.textAlign='center'; c.font=hudFS(TYPE.label); c.fillStyle='#ff6a5a';
    hudText('BOUNTY  $'+BOUNTY.pay,s.x,s.y+ev.r*q+U(16));
  }
};
// FLOW-MODULE-END (the next flow builds add their code above this line)

check:
{v:'VER',what:'flow7, his yes to the bounty pillager event: a ring where he comes in, then a hostile pillager with four times the health, plate and a rich bag hunts the player every frame with the mark and ring on him; downing him pays 1,500 into the score once, a kill that was not the player pays nothing, and after 150 s on the hunt he slips away',
 run:function(){
   if(!(window.__state&&window.__endRaid&&window.__runPrep&&window.__frame)) return 'SKIP: no raid or frame here';
   if(typeof arcadeDeploy!=='function'||typeof ARCADE!=='object') return 'SKIP: no arcade here';
   var bad=[], g=null, p, rs=say, own=false, lines=[], E, ev, ev2, ev3, i, d, e, M, mk, cap=[], proto, oArc, s, hit, m0, saw, needC='BOUNTY '+'CLAIMED';
   function liveIt(x){ for(i=0;i<200&&x.ph==='warn';i++) flowTick(0.25); }
   try{
     __topClear(); __runPrep();
     if(ARCADE.on) return 'SKIP: the arcade is on after __topClear';
     if(!arcadeDeploy({mapIx:0,seed:4242})) return 'SKIP: arcadeDeploy built no arcade raid';
     g=__state(); if(!g||g.over||!g.player) return 'SKIP: no live raid';
     if(typeof evLaunch!=='function'||typeof flowTick!=='function'||!EVENTS.bounty) return 'there is no bounty event in this build';
     p=g.player; keys={};
     say=function(m,kd,o){ lines.push(String(m)+'|'+((o&&o.sub)||'')); }; own=true;
     ARCADE.mine=0; ARCADE.holdT=0; g.t=5; flowTick(0.1); E=g.flow.ev; E.plan.length=0;
     // ONE: a launch, 700 to 1000 away; then the pillager steps in
     ev=evLaunch('bounty');
     if(!ev) return 'SKIP: staging: the bounty found no ground';
     d=Math.hypot(ev.x-p.x,ev.y-p.y);
     if(d<699||d>1001) bad.push('ONE: he comes in '+Math.round(d)+' from the player');
     liveIt(ev); e=ev.d.e;
     if(ev.ph!=='live'||!e) return 'ONE: no pillager after the warning';
     if(e.kind!=='raider'||!e.hostile) bad.push('ONE: the bounty is a '+e.kind+(e.hostile?'':' that is not hostile'));
     if(e.maxhp<78*CFG.eHp*3.9) bad.push('ONE: his health is '+e.maxhp);
     if(!(e.armor>=99)) bad.push('ONE: his plate is '+e.armor);
     if(!(e.bag&&e.bag.length>=3)) bad.push('ONE: his bag holds '+(e.bag?e.bag.length:0));
     if(g.ents.indexOf(e)<0) bad.push('ONE: he is not in the world');
     // TWO: he hunts: each frame on the chase toward where the player stands now
     p.x+=250; p.y+=30; e.state='patrol'; e.alert=0;
     flowTick(0.25);
     if(e.state!=='chase'||!(e.alert>=3)||Math.hypot(e.tx-p.x,e.ty-p.y)>1) bad.push('TWO: he is '+e.state+' with alert '+e.alert+' aimed at '+Math.round(e.tx)+','+Math.round(e.ty));
     // THREE: the mark and the ring are on him
     M=flowMarks(); mk=0; for(i=0;i<M.length;i++) if(M[i].kind==='ev'&&Math.abs(M[i].x-e.x)<1&&Math.abs(M[i].y-e.y)<1) mk++;
     if(!mk) bad.push('THREE: the mark is not on him');
     render2D(0); cap.length=0; proto=CanvasRenderingContext2D.prototype; oArc=proto.arc;
     proto.arc=function(){ cap.push([].slice.call(arguments)); return oArc.apply(this,arguments); };
     try{ flowDraw(ctx,p); } finally { proto.arc=oArc; }
     s=w2s(e.x,0,e.y); hit=0; for(i=0;i<cap.length;i++) if(cap[i].length>=5&&Math.abs(cap[i][0]-s.x)<2&&Math.abs(cap[i][1]-s.y)<2&&Math.abs(cap[i][2]-ev.r*ZOOM())<1.5) hit++;
     if(!hit) bad.push('THREE: no ring was drawn on him ('+cap.length+' arcs)');
     // FOUR: downed by the player: the bounty is paid once, into the score
     m0=ARCADE.mine|0; lines.length=0; e.hp=0; e.byPlayer=true;
     flowTick(0.25);
     if((ARCADE.mine|0)!==m0+BOUNTY.pay) bad.push('FOUR: the bounty paid '+((ARCADE.mine|0)-m0)+', not '+BOUNTY.pay);
     if(ev.ph!=='end') bad.push('FOUR: the event is '+ev.ph+' after he went down');
     saw=0; for(i=0;i<lines.length;i++) if(lines[i].indexOf(needC)>=0) saw=1;
     if(!saw) bad.push('FOUR: no BOUNTY CLAIMED callout');
     for(i=0;i<8;i++) flowTick(0.25);
     if((ARCADE.mine|0)!==m0+BOUNTY.pay) bad.push('FOUR: the bounty was paid again');
     // FIVE: killed by something else: nothing is paid
     ev2=evLaunch('bounty');
     if(ev2){
       liveIt(ev2); e=ev2.d.e; m0=ARCADE.mine|0;
       if(e){ e.hp=0; e.byPlayer=false; flowTick(0.25); if((ARCADE.mine|0)!==m0) bad.push('FIVE: a bounty was paid for a kill that was not the player'); if(ev2.ph!=='end') bad.push('FIVE: the event is '+ev2.ph+' after he was killed'); }
     }
     // SIX: after 150 s on the hunt he slips away
     ev3=evLaunch('bounty');
     if(ev3){
       liveIt(ev3); e=ev3.d.e;
       if(e){ ev3.lt=ev3.dur-0.1; flowTick(0.25); if(ev3.ph!=='end') bad.push('SIX: the hunt never ended ('+ev3.ph+')'); if(g.ents.indexOf(e)>=0) bad.push('SIX: he is still in the world after the hunt'); }
     }
   }catch(x){ bad.push('threw: '+(x&&x.message||x)); }
   finally{
     if(own) say=rs;
     keys={};
     try{ if(proto&&oArc) proto.arc=oArc; }catch(_p){}
     try{ if(typeof ARCADE==='object'&&ARCADE.on) arcadeLeave(); }catch(_l){}
     try{ if(__state()&&!__state().over) __endRaid('abandon'); }catch(_e){}
     try{ if(typeof ARCADE==='object'){ ARCADE.mine=0; ARCADE.waveT=0; ARCADE.holdT=0; } }catch(_h){}
     __topClear();
   }
   return bad.length?bad.slice(0,8).join('; '):null; }},
